use super::*;
fn predecessor()->Value {serde_json::from_str(include_str!("/var/lib/jetstreamer/horizon-recovered-resource-frames-20261029-v1/frame20261107T072809-cached145-original-terminal-reload-native-v1.json")).unwrap()}
#[test] fn genuine0728_b692_predecessor_accepts_distinct_successor_in_outer_envelope() {let p=predecessor();assert_eq!(p["self_sha256"],"b692189704ed9001c016b1931ec6e54210104d36a5fbf787dfdd9d2505ae75eb");qualified_previous_recovery_envelope(&p,&json!({"path":"/genuine0728","sha256":"b".repeat(64)}),&"c".repeat(64)).unwrap();}
#[test] fn genuine0728_outer_envelope_still_rejects_unknown_images_and_native_changes() {let p=predecessor();for (k,v) in [("self_sha256",json!("a".repeat(64))),("accepted_resource_lineage",json!(false)),("full_routine_completion_claimed",json!(true)),("native_census_after",json!({"foreign":true}))] {let mut b=p.clone();b[k]=v;assert!(qualified_previous_recovery_envelope(&b,&json!({"sha256":"b".repeat(64)}),&"c".repeat(64)).is_err(),"{k}");}}
